<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Token Launch Radar — every pre-token protocol, ranked by implied value</title>
<link rel="stylesheet" href="app.css">
</head>
<body>
<header class="top">
  <div class="wrap">
    <div class="title-row">
      <h1>Token Launch Radar</h1>
      <span class="version" id="version"></span>
    </div>
    <p class="sub" id="subline"></p>
    <section class="model-strip" id="model-strip"></section>
  </div>
</header>

<main class="wrap" id="board-view">
  <section class="controls" id="controls">
    <input type="search" id="q" placeholder="Search name, slug or chain…" aria-label="Search">
    <select id="f-cat" aria-label="Category"></select>
    <select id="f-chain" aria-label="Chain"></select>
    <select id="f-verdict" aria-label="Verdict">
      <option value="">All verdicts</option>
      <option value="farm">Farm</option>
      <option value="thin">Thin</option>
      <option value="skip">Skip</option>
    </select>
    <label class="wl-toggle"><input type="checkbox" id="f-wl"> Watchlist only</label>
    <span class="count" id="row-count"></span>
  </section>

  <div class="table-box">
    <table id="board">
      <thead>
        <tr>
          <th data-sort="rank" class="num">#</th>
          <th data-sort="name">Protocol</th>
          <th data-sort="category">Category</th>
          <th data-sort="tvl_usd" class="num">TVL</th>
          <th data-sort="change_7d" class="num">7d</th>
          <th data-sort="age_days" class="num">Age</th>
          <th data-sort="implied_value_usd" class="num">Implied value</th>
          <th class="num">Band (÷/× error)</th>
          <th data-sort="farm_verdict">Verdict</th>
        </tr>
      </thead>
      <tbody id="rows"></tbody>
    </table>
  </div>
  <p class="hint">Click a row for the protocol's detail view and its full farm plan. Click a column heading to sort.</p>

  <section class="live-box">
    <h2>Already trading — set aside, never ranked</h2>
    <p class="hint">These protocols' tokens exist, so the market has already priced them. They are the
    comparables the curve is fitted on (at the $5M scale floor), shown here at the market's own values.</p>
    <div id="live"></div>
  </section>

  <section class="method">
    <h2>How to read this board</h2>
    <div id="method"></div>
  </section>
